"use client";
import { useNotifications } from "@/components/bevelui/notification-center";

export function useCommentActions() {
  const { notify } = useNotifications();

  function onNewComment(comment: { author: string; postId: string }) {
    notify({
      type: "comment",
      groupKey: `comments:${comment.postId}`,
      title: `New comment from ${comment.author}`,
      priority: "normal",
    });
  }

  return { onNewComment };
}

// Three calls, same groupKey → one toast showing "3"
notify({ type: "comment", groupKey: "comments:post-42", title: "Alex commented" });
notify({ type: "comment", groupKey: "comments:post-42", title: "Priya commented" });
notify({ type: "comment", groupKey: "comments:post-42", title: "Sam commented" });
// Toast shows "Sam commented" with a "3" badge — history keeps all three individually.

